/**
 * Tier-2 text, regex, and JSON builders for the calc DSL.
 *
 * All functions in this module produce or consume `Expr<"text">`. They
 * follow the same shape as tier-1: each builder coerces its inputs
 * through `coerce()`, composes their `toCalcString()` outputs into the
 * wire form, and brands the result.
 *
 * Type rules baked in:
 *   - `concat` accepts the scalar families Knowhere can stringify directly:
 *     date, datetime, decimal, number, boolean, and text.
 *   - `len` accepts text only (server rejects numeric).
 *   - `regexMatch` returns bool; the rest return text.
 *   - Argument naming favors readability over wire-form parity
 *     (`needle` / `haystack` for FIND/SEARCH; `pattern` for regex).
 */
import type { ComposedExpr, ExprLike, ExprType } from "./types.js";
/** Types Knowhere currently permits as direct CONCAT arguments. */
export type ConcatExprType = "datetime" | "date" | "decimal" | "number" | "bool" | "text";
/**
 * Concatenate two or more expressions into a single text value.
 * Non-text expressions are stringified by the server. At least two
 * args are required — wire `CONCAT` rejects a single-arg call.
 */
export declare function concat<const A extends ExprLike<ConcatExprType>, const B extends ExprLike<ConcatExprType>, const Rest extends readonly ExprLike<ConcatExprType>[]>(a: A, b: B, ...rest: Rest): ComposedExpr<"text", [A, B, ...Rest]>;
/**
 * Coerce any expression to text. Wire `TEXT(value)`. Useful for
 * embedding non-text values inside a string-shaped expression where
 * the server's implicit promotion isn't enough.
 */
export declare function toText<T extends ExprType, const Value extends ExprLike<T>>(value: Value): ComposedExpr<"text", [Value]>;
/** Character length of a text expression. Returns NUMBER. */
export declare function len<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"number", [Value]>;
/** Strip leading/trailing whitespace. */
export declare function trim<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"text", [Value]>;
/** Upper-case. */
export declare function upper<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"text", [Value]>;
/** Lower-case. */
export declare function lower<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"text", [Value]>;
/**
 * Leftmost `n` characters of a text expression. `n` defaults to 1 on
 * the server when omitted. Wire emits `LEFT(text)` or `LEFT(text, n)`.
 */
export declare function left<const Value extends ExprLike<"text">, const N extends ExprLike<"number"> | undefined = undefined>(value: Value, n?: N): ComposedExpr<"text", [Value, N]>;
/**
 * Rightmost `n` characters of a text expression. `n` defaults to 1 on
 * the server when omitted.
 */
export declare function right<const Value extends ExprLike<"text">, const N extends ExprLike<"number"> | undefined = undefined>(value: Value, n?: N): ComposedExpr<"text", [Value, N]>;
/**
 * Substring from `start` (1-indexed) for `length` characters. Wire
 * emits `MID(text, start, length)`.
 */
export declare function mid<const Value extends ExprLike<"text">, const Start extends ExprLike<"number">, const Length extends ExprLike<"number">>(value: Value, start: Start, length: Length): ComposedExpr<"text", [Value, Start, Length]>;
/**
 * Replace every occurrence of `find` with `replace` in `value`. Wire
 * emits `SUBSTITUTE(value, find, replace)`. For pattern-based
 * replacement use `regexReplace`.
 */
export declare function substitute<const Value extends ExprLike<"text">, const Find extends ExprLike<"text">, const Replace extends ExprLike<"text">>(value: Value, find: Find, replace: Replace): ComposedExpr<"text", [Value, Find, Replace]>;
/**
 * Case-sensitive index of `needle` within `haystack` (1-indexed).
 * `start` is the 1-indexed position to begin searching from. Wire:
 * `FIND(needle, haystack)` / `FIND(needle, haystack, start)`.
 */
export declare function find<const Needle extends ExprLike<"text">, const Haystack extends ExprLike<"text">, const Start extends ExprLike<"number"> | undefined = undefined>(needle: Needle, haystack: Haystack, start?: Start): ComposedExpr<"number", [Needle, Haystack, Start]>;
/**
 * Case-INsensitive variant of `find`. Wire: `SEARCH(...)`.
 */
export declare function search<const Needle extends ExprLike<"text">, const Haystack extends ExprLike<"text">, const Start extends ExprLike<"number"> | undefined = undefined>(needle: Needle, haystack: Haystack, start?: Start): ComposedExpr<"number", [Needle, Haystack, Start]>;
/**
 * Split a text expression by a separator. Wire `SPLIT(text, sep)`.
 * The server returns a text array internally; in expression context
 * it surfaces as a multi-valued text. Note the method name
 * `splitText` to avoid colliding with Array.prototype.split or the
 * JS keyword `split` in `calc.split` — `splitText` reads cleanly in
 * the calc namespace.
 */
/** @deprecated Prefer {@link split}. */
export declare function splitText<const Value extends ExprLike<"text">, const Separator extends ExprLike<"text">>(value: Value, separator: Separator): ComposedExpr<"text", [Value, Separator], "multiple">;
/** Canonical concise name for the multi-valued SPLIT function. */
export declare const split: typeof splitText;
/**
 * Regex match test. Wire `REGEXMATCH(text, pattern)` or
 * `REGEXMATCH(text, pattern, TRUE)` for case-insensitive matching.
 * The `ignoreCase` flag is a bool literal on the wire — TS accepts a
 * raw boolean here so the agent doesn't have to wrap it.
 */
export declare function regexMatch<const Value extends ExprLike<"text">, const Pattern extends ExprLike<"text">>(value: Value, pattern: Pattern, options?: boolean | {
    readonly ignoreCase?: boolean;
}): ComposedExpr<"bool", [Value, Pattern]>;
/**
 * Regex search-and-replace. Wire `REGEXREPLACE(text, pattern, repl)`
 * or `REGEXREPLACE(text, pattern, repl, TRUE)` for case-insensitive.
 */
export declare function regexReplace<const Value extends ExprLike<"text">, const Pattern extends ExprLike<"text">, const Replacement extends ExprLike<"text">>(value: Value, pattern: Pattern, replacement: Replacement, options?: boolean | {
    readonly ignoreCase?: boolean;
}): ComposedExpr<"text", [Value, Pattern, Replacement]>;
/**
 * Regex extract — returns the first matching substring (or capture
 * group) as text. Wire `REGEXEXTRACT(text, pattern)`.
 */
export declare function regexExtract<const Value extends ExprLike<"text">, const Pattern extends ExprLike<"text">>(value: Value, pattern: Pattern): ComposedExpr<"text", [Value, Pattern]>;
/** Escape a text value for embedding in a JSON string literal. */
export declare function jsonEscape<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"text", [Value]>;
/** Reverse the effect of `jsonEscape` — decode a JSON-escaped string. */
export declare function jsonUnescape<const Value extends ExprLike<"text">>(value: Value): ComposedExpr<"text", [Value]>;
/** Repeat text a whole-number count of times. Wire `REPT(text, count)`. */
export declare function repeat<const Value extends ExprLike<"text">, const Count extends ExprLike<"number">>(value: Value, count: Count): ComposedExpr<"text", [Value, Count]>;
